<body>
<main>
  <h1>Memory Match</h1>
  <p class="subtitle">Flip two cards to find matching pairs. Clear all 8 pairs to win!</p>
  <div class="stats" aria-live="polite">
    <div class="stat">Moves: <span id="moves">0</span></div>
    <div class="stat">Pairs: <span id="pairs">0</span>/8</div>
    <div class="stat">Best: <span id="best">—</span></div>
  </div>
  <div class="win" id="win">
    <h2>🎉 You won!</h2>
    <p id="win-msg"></p>
    <button class="btn" onclick="startGame()">Play Again</button>
  </div>
  <div class="board" id="board" role="grid" aria-label="Memory game board"></div>
  <button class="btn" onclick="startGame()">New Game</button>
</main>
<script>
const EMOJIS = ['🐶','🐱','🦊','🐸','🦋','🌸','🍄','🌈'];
let cards=[], flipped=[], matched=0, moves=0, locked=false;

async function getBest(){
  if(window.alfy&&window.alfy.storage){
    try{ return await window.alfy.storage.get('memory-best'); }catch(e){}
  }
  return null;
}
async function setBest(v){
  if(window.alfy&&window.alfy.storage){
    try{ await window.alfy.storage.set('memory-best',v); }catch(e){}
  }
}

function shuffle(a){
  for(let i=a.length-1;i>0;i--){
    const j=Math.floor(Math.random()*(i+1));
    [a[i],a[j]]=[a[j],a[i]];
  }
  return a;
}

async function startGame(){
  cards=shuffle([...EMOJIS,...EMOJIS]);
  flipped=[]; matched=0; moves=0; locked=false;
  document.getElementById('moves').textContent='0';
  document.getElementById('pairs').textContent='0';
  document.getElementById('win').classList.remove('show');
  const board=document.getElementById('board');
  board.innerHTML='';
  cards.forEach((emoji,i)=>{
    const btn=document.createElement('button');
    btn.className='card';
    btn.setAttribute('role','gridcell');
    btn.setAttribute('aria-label','Card '+(i+1));
    btn.innerHTML='<span class="face">'+emoji+'</span>';
    btn.addEventListener('click',()=>flipCard(i,btn));
    board.appendChild(btn);
  });
  const best=await getBest();
  document.getElementById('best').textContent=best!==null?best:'—';
}

async function flipCard(i,btn){
  if(locked||btn.classList.contains('flipped')||btn.classList.contains('matched'))return;
  btn.classList.add('flipped');
  flipped.push({i,btn});
  if(flipped.length===2){
    locked=true; moves++;
    document.getElementById('moves').textContent=moves;
    if(cards[flipped[0].i]===cards[flipped[1].i]){
      flipped[0].btn.classList.add('matched');
      flipped[1].btn.classList.add('matched');
      matched++;
      document.getElementById('pairs').textContent=matched;
      flipped=[]; locked=false;
      if(matched===8){
        document.getElementById('win').classList.add('show');
        document.getElementById('win-msg').textContent='Completed in '+moves+' moves.';
        const best=await getBest();
        if(best===null||moves<best){
          await setBest(moves);
          document.getElementById('best').textContent=moves;
        }
      }
    } else {
      setTimeout(()=>{
        flipped[0].btn.classList.remove('flipped');
        flipped[1].btn.classList.remove('flipped');
        flipped=[]; locked=false;
      },700);
    }
  }
}

startGame();
</script>
</body>
